function Tag({children, tone="sage"}:{children:React.ReactNode;tone?:string}) { return <span className={`tag ${tone}`}>{children}</span> }
function Button({children, variant="primary", href, onClick, type="button", disabled=false}:{children:React.ReactNode;variant?:string;href?:string;onClick?:()=>void;type?:"button"|"submit";disabled?:boolean}) { const cls=`btn ${variant}`; return href ? <Link href={href} className={cls} aria-disabled={disabled}>{children}</Link> : <button type={type} onClick={onClick} className={cls} disabled={disabled}>{children}</button> }
function SectionTitle({eyebrow,title,action}:{eyebrow?:string;title:string;action?:React.ReactNode}) { return <div className="section-title">{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2>{action && <div className="section-action">{action}</div>}</div> }
function SaveButton({label="Save"}:{label?:string}) { const [saved,setSaved] = useState(false); return <button className={`save ${saved?"saved":""}`} aria-label={saved?"Remove saved item":label} onClick={(e) => {e.preventDefault();e.stopPropagation();setSaved(v=>!v);notify(saved?"Removed from saved":"Saved for later");}}>{saved?<Heart size={17} fill="currentColor"/>:<Heart size={17}/>}</button> }
function DestinationCard({d, compact=false}:{d:any;compact?:boolean}) { const Icon=d.icon; const href=`/explore/${slugify(d.name)}`; return <article className={`destination-card ${compact?"compact":""}`}><Link href={href} className="image-wrap"><img src={d.image} alt={d.name}/>{d.placeholder&&<Tag tone="ochre">Placeholder listing</Tag>}</Link><SaveButton/><div className="card-body"><div className="card-heading"><Link href={href}><h3>{d.name}</h3></Link><Icon size={16} className="type-icon"/></div><p className="muted"><MapPin size={14}/>{d.place}</p><p className="desc">{d.description}</p><div className="card-footer"><Tag>{d.type}</Tag>{d.rating?<span className="rating"><Star size={14} fill="currentColor"/> {d.rating} <small>({d.reviews})</small></span>:<span className="unrated">{d.placeholder?"Details pending":"Curated place"}</span>}</div></div></article> }
function BundleCard({b}:{b:any}) { const href=`/bundles/${slugify(b.name)}`; return <article className="bundle-card"><Link href={href} className="image-wrap"><img src={b.image} alt={b.name}/><span className="bundle-curated-badge">Curated route</span></Link><div className="card-body"><span className="bundle-curated-label">Curated route</span><Link href={href}><h3>{b.name}</h3></Link><p className="muted">{b.meta} <span>·</span> <Users size={14}/> 2–6</p><p className="bundle-card-description">{b.description}</p><div className="bundle-card-facts"><span><Clock3 size={13}/>{b.pace}</span><span><MapPin size={13}/>{b.stops.length} stops</span></div><div className="card-footer"><div>{b.tags.map((t:string)=><Tag key={t}>{t}</Tag>)}</div><small>{b.idealFor}</small></div><Button href={href} variant="outline">View Trip <ArrowRight size={14}/></Button></div></article> }
function useLandingMotion() {
  useEffect(() => {
    const nodes = Array.from(document.querySelectorAll<HTMLElement>("[data-scroll-reveal]"));
    if (!nodes.length) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches || !("IntersectionObserver" in window)) {
      nodes.forEach(node => node.classList.add("is-visible"));
      return;
    }
    const observer = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add("is-visible");
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.14, rootMargin: "0px 0px -8%" });
    nodes.forEach(node => observer.observe(node));
    return () => observer.disconnect();
  }, []);
}

